import warnings; warnings.filterwarnings('ignore')
from scipy.optimize import least_squares
def fit(f,p0,n=12):
    best=None
    for s in range(n):
        p=np.random.RandomState(s).randn(len(p0))*0.7+np.array(p0)
        try:
            r=least_squares(lambda p: f(p)-dA_dt, p, max_nfev=1500)
            if np.isfinite(r.cost) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    return np.round(best.x,4), round(1-2*best.cost/np.sum((dA_dt-dA_dt.mean())**2),6)
